actions.script:
const out = ec.service.sync().name('ironstone.commons.CalendarServices.get#EventSummary').parameters({workEffortId: workEffortId || '',
    instanceStart: instanceStart || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() || !out.visible ? {visible: false} : {visible: true, event: out.event})

const L = (text) => ec.l10n.localize(text)
const ids = String(partyIds || '').split(',').map((id) => id.trim()).filter((id) => id)
const me = ec.user.userAccount?.partyId
if (me && !ids.includes(me)) ids.unshift(me)
const day = /^\d{4}-\d{2}-\d{2}$/.test(String(fromDay || '')) ? String(fromDay) : ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd')
const days = Math.min(14, Math.max(1, Number(dayCount) || 5))
const pattern = 'yyyy-MM-dd HH:mm:ss.SSS'
const fromMs = Number(String(ec.l10n.parseTimestamp(day + ' 00:00:00.000', pattern)))
const [y, m, d] = day.split('-').map(Number)
const lastDay = new Date(Date.UTC(y, m - 1, d + days)).toISOString().substring(0, 10)
const thruMs = Number(String(ec.l10n.parseTimestamp(lastDay + ' 00:00:00.000', pattern)))
const out = ec.service.sync().name('mantle.work.EventServices.get#FreeBusy').parameters({partyIdList: ids, facilityIdList: facilityId ? [facilityId] : [],
    fromDate: new Date(fromMs), thruDate: new Date(thruMs), workingHoursOnly: workingHoursOnly !== 'N',
    durationMinutes: Math.max(15, Number(durationMinutes) || 60), slotMinutes: 30, suggestionLimit: 12}).call()
if (ec.message.hasError()) { ec.web.sendJsonResponse({}); return }
const fmt = (value, format) => ec.l10n.format(value, format)
ec.web.sendJsonResponse({slotList: Array.from(out.suggestedSlotList || []).map((slot) => ({start: fmt(slot.fromDate, 'yyyy-MM-dd HH:mm'),
    end: fmt(slot.thruDate, 'yyyy-MM-dd HH:mm'), text: fmt(slot.fromDate, 'EEE, MMM d · h:mm a') + ' – ' + fmt(slot.thruDate, 'h:mm a')})),
    partyIds: ids, note: Array.from(out.suggestedSlotList || []).length ? null : L('No time when everyone is free in those days')})

const id = workEffortId || ''
ec.service.sync().name('ironstone.commons.CalendarServices.get#EventAccessInfo').parameters({workEffortId: id, need: 'edit'}).call()
if (ec.message.hasError()) { ec.web.sendJsonResponse({}); return }
const theScope = scope || 'all'
// the notifications open the event: an instance changed on its own by the series and the instance's start
const eventUrl = '/qapps/Commons/Calendar/EventDetail?workEffortId=' + encodeURIComponent(id)
        + (instanceStart && theScope !== 'all' ? '&instanceStart=' + encodeURIComponent(instanceStart) : '')
const out = ec.service.sync().name('mantle.work.EventServices.update#EventOccurrence').parameters({workEffortId: id,
    instanceStart: instanceStart || null, scope: theScope, start: start || null, end: end || null, allDay: allDay || null,
    notify: notify || 'N', eventUrl: eventUrl, allowConflicts: allowConflicts === 'Y' || allowConflicts === 'true'}).call()
if (ec.message.hasError()) { ec.web.sendJsonResponse({bookingClash: / is booked then: /.test(ec.message.getErrorsString())}); return }
const clashes = Array.from(out.conflictList || [])
ec.web.sendJsonResponse({targetWorkEffortId: out.targetWorkEffortId, messageInfos: [{type: 'success', message: out.message}].concat(clashes.length
    ? [{type: 'warning', message: ec.resource.expand('Booked then too: ${list}', '', {list: Array.from(new Set(clashes.map((clash) =>
        clash.resourceName + ' (' + clash.workEffortName + ')'))).join(', ')})}] : [])})

const out = ec.service.sync().name('ironstone.commons.CalendarServices.respond#Invitation').parameters({workEffortId: workEffortId || '',
    response: response || '', message: message || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {statusId: out.statusId, messageInfos: [{type: 'success', message: out.resultMessage}]})

const out = ec.service.sync().name('ironstone.commons.CalendarServices.export#CalendarFile').parameters({calendarId: calendarId || ''}).call()
if (!ec.message.hasError() && out?.location) ec.web.sendResourceResponse(out.location, false)
else ec.web.sendJsonResponse({})
